import java.util.HashMap;
import java.util.Map;
import java.util.Objects;

public class Main {
    static int spread(int h) {
        return h ^ (h >>> 16);
    }

    static int indexFor(Object key, int capacity) {
        return (capacity - 1) & spread(key.hashCode());
    }

    static final class UserKey {
        final String id;
        UserKey(String id) { this.id = id; }
        public boolean equals(Object o) {
            return o instanceof UserKey other && Objects.equals(id, other.id);
        }
        public int hashCode() { return Objects.hash(id); }
    }

    static final class MutableKey {
        String id;
        MutableKey(String id) { this.id = id; }
        public boolean equals(Object o) {
            return o instanceof MutableKey other && Objects.equals(id, other.id);
        }
        public int hashCode() { return Objects.hash(id); }
    }

    public static void main(String[] args) {
        String key = "order-42";
        int h = spread(key.hashCode());
        int oldIndex = (16 - 1) & h;
        int newIndex = (32 - 1) & h;
        String resizeRule = ((h & 16) == 0) ? "stay in old bucket" : "move to oldIndex + oldCap";

        System.out.println("old index @16: " + oldIndex);
        System.out.println("new index @32: " + newIndex);
        System.out.println("resize rule: " + resizeRule);

        Map<UserKey, String> ok = new HashMap<>();
        ok.put(new UserKey("42"), "first");
        ok.put(new UserKey("42"), "second");
        System.out.println("same logical key size: " + ok.size());
        assert ok.size() == 1;
        assert "second".equals(ok.get(new UserKey("42")));

        Map<MutableKey, String> broken = new HashMap<>();
        MutableKey mk = new MutableKey("before");
        broken.put(mk, "value");
        mk.id = "after";
        System.out.println("lookup after key mutation: " + broken.get(mk));
        assert broken.get(mk) == null;

        assert indexFor("same", 16) >= 0;
        assert newIndex == oldIndex || newIndex == oldIndex + 16;
    }
}
